import { animate, createTimeline, stagger, createScope, utils } from 'animejs';

const main=document.querySelector('main'), drawer=document.querySelector('#drawer'), media=matchMedia('(prefers-reduced-motion: reduce)');
const state={boot:null,scan:null,summary:null,route:'check',job:null,filter:'All',category:'',page:'',search:'',status:'',selected:null,listPage:1,pageIndex:0,preview:'desktop',drawerReturn:null,scope:null,loadToken:0};
let options={},pollTimer=null;
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cube=(size=80)=>`<svg width="${size}" height="${size}" viewBox="0 0 120 120" aria-hidden="true"><use href="#cube"/></svg>`;
const badge=severity=>`<span class="pill-label ${severity==='Needs fixing'?'fix':''}">${severity==='Needs fixing'?'■':severity==='Review'?'△':'◇'} ${e(severity)}</span>`;
const number=v=>String(v).padStart(2,'0');
const date=v=>new Date(v).toLocaleString(undefined,{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
const domain=url=>{try{return new URL(url).host;}catch{return url;}};
const path=url=>{try{let u=new URL(url);return u.pathname+u.search;}catch{return url;}};
const artifact=path=>'/api/artifact?path='+encodeURIComponent(path);
const safeURL=url=>/^https?:\/\//i.test(url)?url:'#';
const splits=text=>text.split('\n').map(s=>s.trim()).filter(Boolean);
const button=(label,action,klass='',attrs='')=>`<button class="button ${klass}" data-action="${action}" ${attrs}>${label}</button>`;
const empty=(heading,copy,action='')=>`<div class="empty reveal">${cube()}<h2>${e(heading)}</h2><p>${e(copy)}</p>${action}</div>`;
function header(kicker,title,copy='',actions=''){return `<div class="page-head reveal"><div><span class="label">${e(kicker)}</span><h1>${e(title)}</h1>${copy?`<p>${e(copy)}</p>`:''}</div><div class="head-actions">${actions}</div></div>`;}
function toast(message){const el=document.createElement('div');el.className='toast';el.innerHTML=`<span>${e(message)}</span><button aria-label="Dismiss notification">×</button>`;document.querySelector('#toasts').replaceChildren(el);if(!media.matches)animate(el,{opacity:[0,1],y:[12,0],duration:220,ease:'out(3)'});let timer=setTimeout(close,4500);function close(){clearTimeout(timer);if(media.matches)el.remove();else animate(el,{opacity:0,y:6,duration:150,ease:'in(2)',onComplete:()=>el.remove()});}el.querySelector('button').onclick=close;}
async function api(url,data){const res=await fetch(url,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-Requested-With':'WebsiteChecker'},body:data===undefined?undefined:JSON.stringify(data)});const json=await res.json();if(!res.ok){const error=new Error(json.error||'The request could not finish.');error.detail=json.detail;throw error;}return json;}
async function refresh(){state.boot=await api('/api/boot');if(!Object.keys(options).length)options={...state.boot.options,...state.boot.settings.brand_rules};}
function motion(){state.scope?.revert();state.scope=createScope({root:main}).add(()=>{if(media.matches)return;createTimeline({defaults:{duration:320,ease:'out(3)'}}).add([...main.querySelectorAll('.reveal')].slice(0,12),{opacity:[0,1],y:[9,0],delay:stagger(25)},0);const cubes=main.querySelectorAll('.hero-cube');if(cubes.length)animate(cubes,{opacity:[0,1],delay:stagger(40),duration:450,ease:'out(3)'});const nums=main.querySelectorAll('[data-count]');nums.forEach(el=>{let target=Number(el.dataset.count),v={n:0};animate(v,{n:target,duration:380,ease:'out(3)',onUpdate:()=>el.textContent=number(Math.round(v.n))});});});}
function updateNav(){document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===state.route||(a.dataset.nav==='check'&&state.route==='report')||(a.dataset.nav==='history'&&['compare','schedules'].includes(state.route))||(a.dataset.nav==='help'&&state.route==='settings')));}
function geometricHero(){return `<div class="hero-graphic reveal"><svg viewBox="0 0 440 425" role="img" aria-label="An interconnected structure of wireframe cubes representing a website"><path d="M55 18H404V396H20V100H55V18M404 240V286M404 308V354" fill="none" stroke="currentColor" stroke-width=".8"/><path d="M16 386h35M20 369v35M388 15v16M380 23h16" stroke="currentColor" stroke-width=".8"/><g class="hero-cube" transform="translate(1,30)"><path d="M0 61h74v282H0zM0 61 37 24h74v282L74 343M74 61l37-37M37 24v282H0" stroke="currentColor" fill="none" stroke-width="1"/><path d="M74 61 111 24v282l-37 37z" fill="currentColor"/></g><g transform="translate(129,46)"><circle cx="49" cy="55" r="45" fill="none" stroke="currentColor"/><circle cx="73" cy="31" r="45" fill="currentColor"/><circle cx="49" cy="55" r="45" fill="white"/><path d="M73-14a45 45 0 0 0-45 45 45 45 0 0 0 45 45" fill="none" stroke="currentColor"/></g><g class="hero-cube" transform="translate(268,36)"><use href="#cube" width="130" height="130"/></g><g class="hero-cube" transform="translate(132,168)"><use href="#cube" width="130" height="130"/></g><g class="hero-cube" transform="translate(268,168)"><use href="#cube" width="130" height="130"/></g><g class="hero-cube" transform="translate(132,298)"><use href="#cube" width="130" height="130"/></g><g class="hero-cube" transform="translate(268,298)"><use href="#cube" width="130" height="130"/></g></svg><div class="graphic-caption"><span>STRUCTURE  SIGNAL  ACTION</span><span>FIG. 01</span></div></div>`;}
function landing(){return `<section class="container hero"><div class="hero-left"><div class="eyebrow label reveal">WEBSITE ANALYSIS / BUILT TO INSPECT</div><h1 class="reveal">Know your<br>website.<br><em>Inside out.</em></h1><p class="hero-copy reveal">Look closer at the details that make a website work. Check its structure, find the issues, and turn real findings into useful next steps.</p><form id="url-form" class="url-form reveal"><label class="label" for="website-url">ENTER YOUR WEBSITE</label><div class="input-row" style="margin-top:10px"><input id="website-url" name="url" type="text" inputmode="url" autocomplete="url" placeholder="https://your-website.com" required aria-describedby="url-help"><button type="submit">RUN CHECK </button></div><div class="form-meta"><label class="check-label"><input type="checkbox" name="consent" required><span>I own this site or have permission to check it.</span></label><button type="button" class="text-button" data-action="scan-settings">SCAN SETTINGS </button></div><div id="url-error" role="alert"></div></form><div class="hero-foot reveal" id="url-help"><span>PUBLIC WEBSITES</span><span>READ ONLY CHECKS</span><span>OPTIONAL AI REVIEWS</span></div></div>${geometricHero()}</section><section class="inspection-band"><div class="reveal"><span class="label">THE INSPECTION SYSTEM</span><h2>A website is more<br>than its first impression.</h2><p>Inspect the details behind the interface. Clear evidence tells you where to look. Practical recommendations help you decide what to fix.</p></div><div class="inspection-list reveal">${['Links & destinations','Page structure & accessibility signals','Images & content','Metadata & technical checks','Browser previews, when enabled'].map(label=>`<div>${label}</div>`).join('')}</div></section><section class="history-strip reveal"><div><h3 style="margin-top:10px">Keep the fixes in view.</h3><p>Saved scans, review notes, comparisons, and reports.</p></div>${button('OPEN HISTORY ','history')}</section>`;}
function scanning(){const stages=[['connecting','Connecting to website'],['pages','Inspecting pages & HTML'],['destinations','Checking links & resources'],['content','Reviewing content & technical findings'],...(state.job.options.browser?[['browser','Rendering browser previews']]:[]),['preparing','Preparing your report']];const idx=Math.max(0,stages.findIndex(x=>x[0]===state.job.phase));return `<section class="container scan-view"><div class="scan-title reveal"><div><span class="label">ANALYSIS IN PROGRESS</span><h1>Following the structure.</h1><p>${e(state.job.url)}</p></div>${button('CANCEL SCAN','cancel','small')}</div><div class="scan-workspace"><div class="scan-graphic reveal"><span class="label">LIVE INSPECTION / FIG. 02</span><svg viewBox="0 0 330 330" aria-hidden="true">${Array.from({length:9},(_,i)=>`<g transform="translate(${(i%3)*108},${Math.floor(i/3)*108})"><g class="scan-cube" data-cube="${i}"><use href="#cube" width="105" height="105"/></g></g>`).join('')}</svg><div class="scan-signal" role="progressbar" aria-label="Completed scan work" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.floor(state.job.percent||0)}"></div></div><div class="reveal"><div class="scan-progress-heading"><span class="label muted">REAL CHECKS. LIVE ACTIVITY.</span><span class="label" id="scan-percent">${Math.floor(state.job.percent||0)}%</span></div><div class="scan-stages">${stages.map(([key,label],i)=>`<div class="stage-row ${i===idx?'current':i<idx?'done':''}" data-stage="${key}"><span class="stage-no">${i<idx?'✓':number(i+1)}</span><span>${label}</span><span class="stage-state">${i===idx?'ACTIVE':i<idx?'COMPLETE':'WAITING'}</span></div>`).join('')}</div><div class="scan-message" role="status" aria-live="polite">${e(state.job.message)}</div><p class="small-note">Completed work across weighted scan stages, not a time estimate. Progress pauses during pending requests. Browser previews run only when enabled.</p></div></div></section>`;}
function updateProgress(job){state.job=job;const message=main.querySelector('.scan-message');if(message&&message.textContent!==job.message)message.textContent=job.message;const rows=[...main.querySelectorAll('.stage-row')];let idx=rows.findIndex(r=>r.dataset.stage===job.phase);if(idx<0)idx=job.state==='completed'?rows.length:0;rows.forEach((r,i)=>{r.classList.toggle('current',i===idx);r.classList.toggle('done',i<idx);r.querySelector('.stage-state').textContent=i===idx?'ACTIVE':i<idx?'COMPLETE':'WAITING';r.querySelector('.stage-no').textContent=i<idx?'✓':number(i+1);});const percent=Math.max(0,Math.min(100,job.percent||0)),line=main.querySelector('.scan-signal');if(!line||line.dataset.percent===String(percent))return;line.dataset.percent=String(percent);state.progressAnimation?.pause();const value={n:Number(line.dataset.shown||0)};const paint=()=>{if(!line.isConnected)return;const shown=value.n,done=Math.floor(shown*9/100),active=Math.min(8,done);line.dataset.shown=String(shown);line.style.transform=`scaleX(${shown/100})`;line.setAttribute('aria-valuenow',String(Math.floor(shown)));const label=main.querySelector('#scan-percent');if(label)label.textContent=Math.floor(shown)+'%';main.querySelectorAll('.scan-cube').forEach((c,i)=>{const status=i<done?'complete':i===active?'active':'waiting';if(c.dataset.status===status)return;utils.remove(c);c.dataset.status=status;c.style.opacity=status==='waiting'?'.2':'1';c.style.transform='';if(!media.matches)state.scope.add(()=>animate(c,{opacity:shown===100?[.8,1]:status==='waiting'?.2:1,scale:status==='active'?[1,1.035,1]:1,y:status==='active'?[0,-3,0]:0,duration:status==='active'?300:180,ease:'out(3)'}));});};if(media.matches||percent===100){value.n=percent;paint();}else state.scope.add(()=>{state.progressAnimation=animate(value,{n:percent,duration:300,ease:'out(3)',onUpdate:paint});});}


async function beginScan(url,consent,scanOptions=options){const job=await api('/api/scan',{url,consent,options:scanOptions});sessionStorage.setItem('wqc_job',job.job_id);state.job=await api('/api/job/'+job.job_id);state.route='check';location.hash='#check';render();updateProgress(state.job);poll(job.job_id);}
async function poll(id){clearTimeout(pollTimer);try{const job=await api('/api/job/'+id);state.job=job;if(job.state==='completed'){if(state.route==='check'){updateProgress(job);await new Promise(requestAnimationFrame);}sessionStorage.removeItem('wqc_job');state.job=null;await refresh();toast('Analysis saved. Your findings are ready.');location.hash='#report/'+job.scan_id+'/findings';await route();return;}if(job.state==='cancelled'){sessionStorage.removeItem('wqc_job');state.job=null;render();toast('Scan cancelled.');return;}if(job.state==='failed'){sessionStorage.removeItem('wqc_job');renderError(job.message,job.detail,true);return;}if(state.route==='check')updateProgress(job);pollTimer=setTimeout(()=>poll(id),650);}catch(err){renderError('We lost contact with this scan.',err.message,true);}}
function countsHTML(data=state.summary){return ['Needs fixing','Review',"Couldn't verify",'Verified'].map(label=>{const count=label==='Verified'?data.verified.length:data.counts[label];return `<div class="metric"><span class="number" data-count="${count}">${number(count)}</span><span class="label">${e(label)}</span></div>`;}).join('');}
function report(){const s=state.scan,summary=state.summary,tab=location.hash.split('/')[2]||'findings';const categories=s.options.categories||[];return `<section class="container">${header('WEBSITE ANALYSIS / '+date(s.created),domain(s.url),'Inspect the findings. Understand the evidence. Decide what changes next.',button('NEW CHECK ','check')+button('EXPORT REPORT ','tab-report','primary'))}<div class="audit-summary reveal"><div><span class="label">OVERALL ASSESSMENT</span><h2 class="summary-title">${e(summary.status)}.</h2><p>Based on observed findings. Review suggestions and unverified checks alongside confirmed errors.</p></div><div class="summary-right"><div class="metric-strip">${countsHTML()}</div><div class="block-grid" aria-hidden="true">${Array.from({length:24},(_,i)=>`<span class="${i<Math.min(summary.verified.length,24)?'filled':''}"></span>`).join('')}</div><p style="margin-top:10px;font-size:8px">Each filled block represents a verified destination, up to 24.</p></div></div><div class="coverage"><span><strong>${s.complete?'SCAN COMPLETED':'PARTIAL COVERAGE'}</strong>  ${s.pages.length} HTML page${s.pages.length!==1?'s':''} inspected${s.notes.some(n=>n.includes('SAMPLE DATA'))?'  SAVED SAMPLE DATA':''}</span><button class="text-button" data-action="tab-notes">VIEW SCOPE </button></div><nav class="report-tabs" aria-label="Analysis views">${[['findings','FINDINGS'],['pages','PAGES & PREVIEWS'],['verified','VERIFIED DESTINATIONS'],['report','REPORT'],['notes','SCAN NOTES']].map(([key,label])=>`<button data-action="tab-${key}" class="${tab===key?'active':''}" aria-current="${tab===key?'page':'false'}">${label}</button>`).join('')}</nav><div class="report-body">${tab==='findings'?findings(categories):tab==='pages'?pages():tab==='verified'?verified():tab==='report'?reportExport():scanNotes()}</div></section>`;}
function filteredIssues(){return state.scan.issues.filter(i=>(state.filter==='All'||i.severity===state.filter)&&(!state.category||i.category===state.category)&&(!state.page||i.page===state.page)&&(!state.status||(state.boot.reviews[i.id]?.status||'Open')===state.status)&&(!state.search||JSON.stringify(i).toLowerCase().includes(state.search.toLowerCase()))).sort((a,b)=>({'Needs fixing':0,'Review':1,"Couldn't verify":2}[a.severity]??3)-({'Needs fixing':0,'Review':1,"Couldn't verify":2}[b.severity]??3));}
function findings(categories){let items=filteredIssues();if(!items.some(i=>i.id===state.selected))state.selected=items[0]?.id||null;const shown=items.slice((state.listPage-1)*20,state.listPage*20);const blocker=state.scan.issues.filter(i=>{let r=state.boot.reviews[i.id]||{};return r.blocker&&!['Fixed (manual)','Intentional'].includes(r.status)}).length;return `<div class="category-strip reveal">${categories.map(c=>{let count=state.scan.issues.filter(i=>i.category===c).length;return `<button class="category-cell ${state.category===c?'active':''}" data-action="category" data-value="${e(c)}" aria-pressed="${state.category===c}"><span>${e(c)}<strong>${number(count)}</strong></span></button>`}).join('')}</div><div class="section-heading"><div><h2>Findings & fixes.</h2><p style="margin-top:9px">Start with confirmed errors. Review suggestions in context.</p></div><span class="label">${number(state.scan.issues.length)} OBSERVED</span></div>${blocker?`<div class="note-box">■ ${blocker} unresolved finding${blocker!==1?'s':''} marked as launch blockers by your team.</div>`:''}<div class="filter-bar"><div>${['All','Needs fixing','Review',"Couldn't verify"].map(f=>`<button class="filter ${state.filter===f?'active':''}" data-action="filter" data-value="${e(f)}" aria-pressed="${state.filter===f}">${e(f)}</button>`).join('')}</div><input class="control" id="issue-search" aria-label="Search findings" placeholder="Search findings…" value="${e(state.search)}"><select class="control" id="issue-page" aria-label="Filter findings by page"><option value="">All pages</option>${state.scan.pages.map(p=>`<option value="${e(p.url)}" ${state.page===p.url?'selected':''}>${e(path(p.url))}</option>`).join('')}</select><select class="control" id="issue-status" aria-label="Filter work status"><option value="">All work statuses</option>${['Open','In progress','Fixed (manual)','Intentional','Needs review'].map(v=>`<option ${state.status===v?'selected':''}>${v}</option>`).join('')}</select>${button('RESET','reset-filters','small')}</div><div id="findings-content">${findingContent(items,shown)}</div>`;}
function findingContent(items,shown){return `<div class="result-count" role="status">${items.length} matching finding${items.length!==1?'s':''}${state.category?' / '+e(state.category):''}</div>${!items.length?empty('Nothing in this view.','No findings match these filters. Reset them to see the full analysis.',button('RESET FILTERS','reset-filters')):`<div class="finding-layout"><div class="finding-list">${shown.map(i=>`<button class="finding-row ${i.id===state.selected?'selected':''}" data-action="select-issue" data-value="${i.id}" aria-pressed="${i.id===state.selected}"><span class="severity-symbol" aria-hidden="true">${i.severity==='Needs fixing'?'■':i.severity==='Review'?'△':'◇'}</span><span><span class="row-title">${e(i.title)}</span><span class="finding-meta"><span>${e(i.severity)}</span><span> ${e(i.category)}</span><span> ${e(state.boot.reviews[i.id]?.status||'Open')}</span></span><span class="finding-url">${e(i.page)}</span></span></button>`).join('')}<div class="detail-actions">${button(' PREVIOUS','previous-issues','small',state.listPage===1?'disabled':'')}<span class="label" style="align-self:center">${state.listPage} / ${Math.max(1,Math.ceil(items.length/20))}</span>${button('NEXT ','next-issues','small',state.listPage*20>=items.length?'disabled':'')}</div></div><div class="finding-detail" id="finding-detail" aria-label="Selected finding details">${detail(state.scan.issues.find(i=>i.id===state.selected))}</div></div>`}`;}
function why(i){const map={Links:'Visitors depend on links to reach the right page or file. An unavailable destination can interrupt their next step.',Images:'Images affect clarity and loading. Review the actual display and download evidence before changing an asset.',Metadata:'Page and sharing metadata explain your content to browsers, search tools and people sharing a link.',Accessibility:'This signal may affect how people perceive or operate the page. Automated findings need context and manual review.',Content:'Unfinished, repeated or unclear content can make information harder to trust and use.',Technical:'This response or configuration can change how a page is reached and interpreted.',Brand:'The observed wording differs from the rules you supplied for this scan.',Performance:'This observation can point to extra download work or delay. A single scan is not a real-user performance measurement.'};return map[i.category]||'Review this evidence in the context of the page before deciding on a change.';}
function detail(i){if(!i)return empty('Select a finding.','Choose a row to inspect its evidence and recommended fix.');const r=state.boot.reviews[i.id]||{};return `<div class="detail-top">${button(' BACK TO FINDINGS','detail-back','small mobile-detail-back')}${badge(i.severity)}<h3>${e(i.title)}</h3><span class="label">${e(i.category)} / ${e(r.status||'Open')}</span></div><div class="detail-section"><span class="label">WHAT WAS DETECTED</span><p>${e(i.evidence)}</p></div><div class="detail-section"><span class="label">WHY IT MATTERS</span><p>${e(why(i))}</p></div><div class="detail-section"><span class="label">WHERE TO LOOK</span><code>${e(i.page)}${i.target?'\n\nTarget: '+e(i.target):''}</code><button class="text-button" data-action="copy" data-value="${e(i.target||i.page)}">COPY LOCATION </button></div><div class="detail-section fix"><span class="label">RECOMMENDED FIX</span><p>${e(i.fix)}</p></div>${r.notes?`<div class="detail-section"><span class="label">YOUR REVIEW NOTE</span><p>${e(r.notes)}</p>${r.owner?`<p style="margin-top:8px">Owner: ${e(r.owner)}${r.due?'  Due '+e(r.due):''}</p>`:''}</div>`:''}<div class="detail-actions">${button('REVIEW / ASSIGN ','review','primary',`data-value="${i.id}"`)}${button('RECHECK PAGE ','recheck','',`data-value="${e(i.page)}"`)}${button('ISSUE CARD ','download-card','',`data-value="${i.id}"`)}<a class="button" href="${e(safeURL(i.page))}" target="_blank" rel="noopener noreferrer">OPEN PAGE </a></div>${r.attachment?`<div class="detail-section"><img class="preview-image" src="${artifact(r.attachment)}" alt="Attached review evidence"></div>`:''}`;}
function verified(){const list=state.summary.verified;return `<div class="section-heading"><div><h2>Destinations that responded.</h2><p style="margin-top:10px">${list.length} unique links or resources returned a successful response.</p></div><span class="label">✓ VERIFIED</span></div><div class="note-box">A passed destination check confirms the observed HTTP response. It does not certify the page's accessibility, content, security or overall quality.</div>${list.length?`<div class="table-wrap"><table><thead><tr><th>Destination</th><th>HTTP</th><th>Type</th><th>Found on</th></tr></thead><tbody>${list.slice(0,200).map(v=>`<tr><td class="url-cell"><a href="${e(safeURL(v.url))}" target="_blank" rel="noopener noreferrer">${e(v.url)} </a></td><td>✓ ${e(v.status)}</td><td>${e(v.kind)}</td><td class="url-cell">${e(path(v.page))}</td></tr>`).join('')}</tbody></table></div>`:empty('No verified destinations yet.','This scan did not record successful link or resource responses. Check the scan notes for coverage and restrictions.')}`;}
function pageObj(){return state.scan.pages[state.pageIndex]||state.scan.pages[0];}
function pages(){const list=state.scan.pages;if(!list.length)return empty('No pages to preview.','The scanner could not inspect an HTML page. Review the scan notes, then retry with a reachable public URL.',button('NEW CHECK ','check'));const p=pageObj();const shots=p.browser?.screenshots||{};let modes=Object.keys(shots);if(!modes.includes(state.preview))state.preview=modes[0]||'desktop';return `<select class="control page-select" id="page-select" aria-label="Page to inspect">${list.map((p,i)=>`<option value="${i}" ${i===state.pageIndex?'selected':''}>${e(p.url)}</option>`).join('')}</select><div class="preview-layout"><div><div class="preview-options">${modes.map(m=>`<button class="filter ${state.preview===m?'active':''}" data-action="preview" data-value="${e(m)}">${e(m.toUpperCase())}</button>`).join('')}</div>${modes.length?`<img class="preview-image" src="${artifact(shots[state.preview])}" alt="${e(state.preview)} screenshot of ${e(p.url)}"><a class="button small" style="margin-top:12px" href="${artifact(shots[state.preview])}" download>DOWNLOAD PREVIEW </a>`:empty('A closer look, when enabled.','Browser previews were not captured for this page. Enable them in scan settings and install Chromium to capture real screenshots.')}<div class="small-note">${(p.browser?.limitations||[]).map(e).join('<br>')}</div></div><div><div class="metadata"><span class="label">PAGE METADATA</span><h3>${e(p.title||'No page title')}</h3><p>${e(p.description||'No meta description found.')}</p>${[['HTTP response',p.status],['Page language',p.lang||'Not set'],['Click depth',p.depth],['HTML size',Math.round(p.html_bytes/1024)+' KB'],['Fetch time',p.response_seconds+' s']].map(([k,v])=>`<div class="definition"><span>${k}</span><span>${e(v)}</span></div>`).join('')}</div><div class="metadata" style="margin-top:20px"><span class="label">SOCIAL METADATA PREVIEW</span><h3>${e(p.social['og:title']||p.title||'Title not set')}</h3><p>${e(p.social['og:description']||'Social description not set.')}</p><code>Image: ${e(p.social['og:image']||'Not set')}</code><p class="small-note">Metadata only. Platforms can crop and cache previews differently.</p></div></div></div><div class="report-tabs" style="margin-top:30px"><button class="active">PAGE INSPECTION</button></div><div class="help-section"><h2>Structure & connections.</h2><div class="map-links">${list.map((p,i)=>`<button class="map-node ${i===state.pageIndex?'current':''}" data-action="page-node" data-value="${i}">${cube(30)} ${e(path(p.url))}</button>`).join('')}</div><p class="small-note">Select a scanned page to inspect its incoming and outgoing links. This map covers discovered pages, not a full site inventory.</p><div class="table-wrap"><table><thead><tr><th>From</th><th>To</th><th>Link label</th><th>Result</th></tr></thead><tbody>${state.scan.links.filter(l=>l.from===p.url||l.to===p.url).slice(0,100).map(l=>`<tr><td>${e(path(l.from))}</td><td class="url-cell">${e(l.to)}</td><td>${e(l.label)}</td><td>${e(l.result||'Not checked')}</td></tr>`).join('')}</tbody></table></div></div><div class="help-section"><h2>Resources & response observations.</h2><div class="table-wrap"><table><thead><tr><th>Resource</th><th>Type</th><th>Download</th><th>Time</th><th>Result</th></tr></thead><tbody>${state.scan.resources.filter(r=>r.page===p.url).slice(0,200).map(r=>`<tr><td class="url-cell">${e(r.url)}</td><td>${e(r.kind)}</td><td>${r.bytes===undefined?'—':Math.round(r.bytes/1024)+' KB'}</td><td>${r.seconds===undefined?'—':r.seconds+' s'}</td><td>${e(r.result||'Not checked')}</td></tr>`).join('')}</tbody></table></div><p class="small-note">HTML-discovered resources and one-machine fetch timings. These are not Lighthouse scores or Core Web Vitals.</p></div><div class="help-section"><h2>Headings & form structure.</h2><div class="table-wrap"><table><thead><tr><th>Heading</th><th>Text</th></tr></thead><tbody>${p.headings.map(h=>`<tr><td>H${h.level}</td><td>${e(h.text)}</td></tr>`).join('')}</tbody></table></div><p class="small-note">${p.forms.length} form(s) found in source HTML. Automated scanning does not submit them.</p>${p.browser?.keyboard?`<details><summary>Keyboard observations / first 12 Tab stops</summary><pre class="focus-list">${e(JSON.stringify(p.browser.keyboard,null,2))}</pre></details>`:''}</div><div class="help-section"><h2>Your judgment completes the picture.</h2><p>Record keyboard, mobile, form and visual checks with a saved manual checklist.</p>${button('OPEN MANUAL CHECKLIST ','manual','primary')} </div>${state.scan.journey.length?`<div class="help-section"><h2>Journey reachability.</h2><div class="table-wrap"><table><thead><tr><th>Step</th><th>URL</th><th>Response</th><th>Linked from previous</th></tr></thead><tbody>${state.scan.journey.map((s,i)=>`<tr><td>${number(i+1)}</td><td>${e(s.url)}</td><td>${e(s.result)}</td><td>${s.linked_from_previous===null?'First step':s.linked_from_previous===undefined?'Not verified':s.linked_from_previous?'Yes':'Not found in HTML'}</td></tr>`).join('')}</tbody></table></div></div>`:''}`;}
function scanNotes(){return `<div class="section-heading"><h2>Know the scope.</h2><span class="label">EVIDENCE / NOT CERTIFICATION</span></div><div class="note-box">${e(state.summary.score_note)} Severity labels match the backend: Needs fixing, Review, and Couldn't verify. This interface does not invent Critical/High ratings.</div><ul class="notes-list">${state.scan.notes.map(n=>`<li>${e(n)}</li>`).join('')}</ul><details><summary>Scan configuration and technical context</summary><pre class="focus-list">${e(JSON.stringify(state.scan.options,null,2))}</pre></details><p class="small-note">All findings apply to the recorded scan. Source checks and browser previews have different coverage limits. A clean result is not a complete accessibility, security or legal audit.</p>`;}
function reportExport(){const s=state.scan;return `<div class="export-layout"><div class="report-sheet reveal"><div class="report-sheet-head"><div><span class="label">WEBSITE REVIEW / ${e(date(s.created))}</span><h2 style="margin-top:18px">${e(state.boot.settings.report_brand)}</h2><p style="margin-top:15px;font-size:10px;overflow-wrap:anywhere">${e(s.url)}</p></div><div style="color:var(--indigo)">${cube(65)}</div></div><div class="metric-strip">${countsHTML()}</div><h3>${e(state.summary.status)}.</h3><p class="small-note">${s.pages.length} HTML page(s) inspected. ${s.complete?'Scan completed.':'Partial coverage; review the notes before making decisions.'}</p><div class="note-box">Automated observations and guided manual review. No numerical quality score is assigned.</div><h3 style="margin:25px 0">Findings & next steps</h3>${s.issues.slice(0,8).map(i=>`<div class="report-preview-row">${badge(i.severity)}<h4>${e(i.title)}</h4><p>${e(i.fix)}</p><p class="muted">${e(i.page)}</p></div>`).join('')}${s.issues.length>8?`<p class="small-note">${s.issues.length-8} more findings in the complete export.</p>`:''}${!s.issues.length?`<p class="small-note">No findings recorded. Check scope and unverified destinations before interpreting this result.</p>`:''}</div><div class="export-controls reveal"><span class="label">TAKE THE REVIEW WITH YOU</span><h3 style="margin:15px 0 20px">Clear findings.<br>Useful handover.</h3><div class="field"><label for="report-brand">Report heading</label><input id="report-brand" value="${e(state.boot.settings.report_brand)}" maxlength="200"></div>${button('DOWNLOAD PDF ','export-pdf','primary')}${button('DOWNLOAD CSV ','export-csv')}${button('SCAN ARCHIVE ','export-zip')}<p class="small-note">The archive includes page text, notes, screenshots, issue cards and manual checklists. Review it before sharing.</p></div></div>`;}
function history(){const list=state.boot.scans;return `<section class="container">${header('SAVED ANALYSIS','The work, in perspective.','Revisit scans, compare changes, and keep your reviews together.',button('NEW CHECK ','check','primary'))}<div class="history-topline">${button('COMPARE SCANS ','compare')}${button('SCHEDULES ','schedules')}${button('WORKSPACE SETTINGS ','settings')}</div>${list.length?`<div style="padding-bottom:60px">${list.map(s=>`<div class="history-row reveal"><div><div class="site">${e(domain(s.url))}</div><div class="date">${e(path(s.url))}${s.sample?'  SAVED SAMPLE':''}</div></div><div class="history-count"><span class="label">PAGES</span><div class="number" style="font-size:26px;margin-top:5px">${number(s.summary.pages)}</div></div><div class="history-status"><span class="label">FINDINGS</span><div style="margin-top:7px">■ ${s.summary.counts['Needs fixing']} fixing  △ ${s.summary.counts.Review} review</div></div><div class="history-date"><span class="label">SCANNED</span><div class="date" style="margin-top:8px">${e(date(s.created))}</div></div>${button('OPEN ','open-scan','small',`data-value="${s.id}"`)}</div>`).join('')}</div>`:empty('Your next check starts here.','No website has been analyzed in this workspace. Enter a public URL to create your first real report.',button('CHECK A WEBSITE ','check','primary'))}</section>`;}
function reports(){const list=state.boot.scans;return `<section class="container">${header('REPORT LIBRARY','Evidence you can share.','Choose a saved analysis to prepare a report. PDF, CSV and a complete scan archive are available.')}<div style="padding-bottom:60px">${list.length?list.map(s=>`<div class="history-row reveal"><div class="site">${e(domain(s.url))}</div><span class="label">${s.summary.pages} PAGES</span><span>${e(date(s.created))}</span><span>${e(s.summary.status)}</span>${button('REPORT ','open-report','',`data-value="${s.id}"`)}</div>`).join(''):empty('A report needs real findings.','Run your first website check, then return here to review and download the results.',button('RUN A CHECK ','check','primary'))}</div></section>`;}
function help(){return `<section class="container">${header('ABOUT / HELP','A closer look at the web.','A website review workspace that connects observations to practical fixes.')}<div class="help-section"><h2>From URL to useful action.</h2><p>Enter a public website URL, select your checks and run an analysis. Open a finding to see what was detected, why it matters, where it appears, and what to change. Save your review, recheck a page, or export the report.</p></div><div class="help-section"><h2>Know what each result means.</h2>${[['■ Needs fixing','A destination or page returned a confirmed client-side error, such as 404. Review its source location and update it where appropriate.'],['△ Review','An observed signal needs your judgment. A redirect, missing metadata or a small target is not automatically a definitive failure.'],["◇ Couldn't verify",'A destination was blocked, unavailable, rate-limited, timed out or not checked within the scan limits. It is not automatically a broken link.'],['✓ Verified destination','The observed HTTP response was successful. It is not a guarantee about the destination’s content or accessibility.']].map(([q,a])=>`<details><summary>${e(q)}</summary><p>${e(a)}</p></details>`).join('')}</div><div class="help-section"><h2>Answers before the next check.</h2>${[['Where is the overall score?','This backend does not calculate a validated quality score. The interface shows actual findings, verified destinations and coverage instead of fabricating a number.'],['Which checks need Chromium?','Desktop/mobile screenshots, computed contrast, overflow, touch target, keyboard, print and reduced-motion observations require the optional Playwright browser installation. Run: python -m playwright install chromium'],['Why is coverage partial?','A page limit, blocked request, unavailable resource or browser failure can leave part of the site unverified. Read the scan notes and retry or inspect the page manually.'],['Can the checker fix my website?','It explains recommended changes and lets you organize them. It does not modify the target website.'],['What is stored?','This installation stores scan URLs, extracted page text, findings, screenshots, review notes, schedules, settings and saved AI reviews. Optional AI actions send selected evidence and messages to OpenAI only after you allow it. Screenshots are included only when selected. No analytics service is added. Target websites receive scan requests.'],['Can recurring scans run when my laptop is off?','No. Keep python worker.py running on an always-on machine with the same persistent data folder. Notifications appear inside this workspace.'],['Is this a certification?','No. Automated checks are advisory. Accessibility, security, legal compliance, search performance and form behavior require additional review.']].map(([q,a])=>`<details><summary>${e(q)}</summary><p>${e(a)}</p></details>`).join('')}</div><div class="history-strip" style="padding-left:0;padding-right:0"><div><h3>Configure your workspace.</h3><p>Brand rules, report identity, and recurring reviews.</p></div>${button('SETTINGS ','settings')}</div></section>`;}
function settings(){const s=state.boot.settings,r=s.brand_rules;return `<section class="container">${header('WORKSPACE SETTINGS','Make the review yours.','Reusable brand rules and report branding. This installation is a shared workspace for its owner or trusted team.')}<form id="settings-form" class="settings-layout"><div><div class="field"><label for="setting-brand">Default report heading</label><input id="setting-brand" name="report_brand" value="${e(s.report_brand)}" maxlength="200"></div><div class="field"><label for="setting-logo">Report logo / PNG or JPG</label><input id="setting-logo" name="logo" type="file" accept="image/png,image/jpeg"></div><div class="field"><label for="dictionary">Allowed dictionary words / one per line</label><textarea id="dictionary" name="dictionary">${e((r.dictionary||[]).join('\n'))}</textarea></div><div class="field"><label for="required">Required phrases / one per line</label><textarea id="required" name="required_phrases">${e((r.required_phrases||[]).join('\n'))}</textarea><small>Required phrases are checked on every scanned page.</small></div><div class="field"><label for="forbidden">Outdated wording / one per line</label><textarea id="forbidden" name="forbidden_phrases">${e((r.forbidden_phrases||[]).join('\n'))}</textarea></div><button class="button primary" type="submit">SAVE SETTINGS </button></div><div><div class="metadata"><span class="label">BROWSER CHECKS</span><h3 style="margin:15px 0">See the rendered page.</h3><p>Install Chromium once to enable the optional browser inspections.</p><code>python -m playwright install chromium</code></div><div class="metadata" style="margin-top:25px"><span class="label">RECURRING SCANS</span><h3 style="margin:15px 0">Keep the worker running.</h3><p>Schedules need a separate process and persistent disk storage.</p><code>python worker.py</code>${button('OPEN SCHEDULES ','schedules','small')}</div><p class="small-note">The default app runs on localhost. Before hosting for others, configure authentication and durable storage. All admitted workspace users can see its saved data.</p></div></form></section>`;}
function schedules(){const heartbeat=state.boot.heartbeat;const alive=heartbeat&&(Date.now()-new Date(heartbeat))<90000;return `<section class="container">${header('RECURRING REVIEW','Keep a good thing working.','Save daily or weekly scans. The worker runs them while the machine stays on.',button('HISTORY ','history'))}<div class="note-box">${alive?'✓ The scheduler worker recently checked in.':'◇ The worker is not reporting. Saved schedules wait until python worker.py is running.'}</div><form id="schedule-form" class="form-grid" style="max-width:850px"><div class="field"><label for="schedule-scan">Use a saved scan’s URL and options</label><select id="schedule-scan" name="scan_id" required><option value="">Select a real scan</option>${state.boot.scans.filter(s=>!s.sample).map(s=>`<option value="${s.id}">${e(domain(s.url))} / ${e(date(s.created))}</option>`).join('')}</select></div><div class="field"><label for="schedule-hours">Repeat</label><select id="schedule-hours" name="hours"><option value="168">Weekly</option><option value="24">Daily</option></select></div><button class="button primary" type="submit">SAVE SCHEDULE </button></form><div class="help-section"><h2>Saved schedules.</h2>${state.boot.schedules.length?state.boot.schedules.map(j=>`<div class="schedule-row"><div><strong>${e(j.url)}</strong><p class="small-note" style="margin:8px 0">Every ${j.hours} hours  next ${e(date(j.next_run))}</p></div><button class="filter ${j.enabled?'active':''}" data-action="toggle-schedule" data-value="${j.id}" data-enabled="${j.enabled?'false':'true'}" aria-pressed="${!!j.enabled}">${j.enabled?'ENABLED':'PAUSED'}</button></div>`).join(''):empty('No schedule saved.','Choose a real scan above to set up a recurring review.')}</div><div class="help-section"><div class="section-heading"><h2>Workspace notifications.</h2>${button('MARK READ','mark-read','small')}</div>${state.boot.notifications.length?state.boot.notifications.map(n=>`<div class="schedule-row"><div><p>${e(n.message)}</p><span class="label muted">${e(date(n.created))}</span></div><span class="label">${n.seen?'READ':'NEW'}</span></div>`).join(''):'<p class="small-note">No notifications yet. Updates appear here after scheduled reviews. No outbound email or messaging is configured.</p>'}</div></section>`;}
function compare(){const list=state.boot.scans;return `<section class="container">${header('SCAN COMPARISON','The difference is in the details.','Compare findings and captured screenshots. A finding not seen again is not automatically fixed.')} ${list.length<2?empty('One more scan makes a comparison.','Save at least two analyses to compare their observed findings.',button('RUN A CHECK ','check','primary')):`<form id="compare-form" class="form-grid"><div class="field"><label for="compare-before">Earlier scan</label><select id="compare-before" name="before">${list.map((s,i)=>`<option value="${s.id}" ${i===1?'selected':''}>${e(domain(s.url))} / ${e(date(s.created))}</option>`).join('')}</select></div><div class="field"><label for="compare-after">Later scan</label><select id="compare-after" name="after">${list.map(s=>`<option value="${s.id}">${e(domain(s.url))} / ${e(date(s.created))}</option>`).join('')}</select></div><button type="submit" class="button primary">COMPARE </button></form><div id="comparison-output" style="padding-bottom:55px"></div>`}</section>`;}
async function showComparison(before,after){const result=await api('/api/compare?before='+before+'&after='+after);const [a,b]=await Promise.all([api('/api/scan/'+before),api('/api/scan/'+after)]);const shared=a.scan.pages.filter(p=>b.scan.pages.some(q=>q.url===p.url));let shots=[];shared.forEach(p=>{const q=b.scan.pages.find(x=>x.url===p.url);for(const mode of Object.keys(p.browser?.screenshots||{})){if(q.browser?.screenshots?.[mode])shots.push({page:p.url,mode,before:p.browser.screenshots[mode],after:q.browser.screenshots[mode]});}});document.querySelector('#comparison-output').innerHTML=`${!result.comparable?'<div class="note-box">Coverage or options differ, or the later scan is incomplete. “Not seen” is not proof of a fix.</div>':''}${a.scan.url!==b.scan.url?'<div class="note-box">These scans use different starting URLs. Compare their scope carefully.</div>':''}<div class="compare-columns">${[['new','NEW FINDINGS'],['persistent','STILL PRESENT'],['not_seen','NOT SEEN THIS TIME']].map(([key,label])=>`<div class="compare-column reveal"><span class="label">${label}</span><span class="number">${number(result[key].length)}</span><ul>${result[key].slice(0,80).map(i=>`<li>${e(i.title)}<br><span class="muted">${e(i.page)}</span></li>`).join('')}</ul></div>`).join('')}</div><div class="help-section"><h2>Visual changes.</h2>${shots.length?`<select class="control page-select" id="visual-pair" aria-label="Screenshot pair">${shots.map((s,i)=>`<option value="${i}">${e(s.page)} / ${e(s.mode)}</option>`).join('')}</select><div id="visual-output"></div>`:'<p class="small-note">No matching captured screenshots. Enable browser previews on both scans to compare real images.</p>'}</div>`;state.pairs=shots;if(shots.length)await showVisual(0);}
async function showVisual(idx){const pair=state.pairs[idx],out=document.querySelector('#visual-output');out.innerHTML=`<div class="screen-pair"><div><span class="label">BEFORE</span><img src="${artifact(pair.before)}" alt="Earlier scan screenshot"></div><div><span class="label">AFTER</span><img src="${artifact(pair.after)}" alt="Later scan screenshot"></div></div><div id="visual-diff" role="status" style="margin-top:20px">Preparing pixel comparison…</div>`;try{const d=await api('/api/diff?before='+encodeURIComponent(pair.before)+'&after='+encodeURIComponent(pair.after));document.querySelector('#visual-diff').innerHTML=`<p class="small-note">${(d.ratio*100).toFixed(1)}% changed pixels highlighted. Dynamic content, timing and fonts can cause differences.</p><img class="preview-image" src="data:image/png;base64,${d.image}" alt="Screenshot comparison with changed pixels highlighted"><a class="button" href="data:image/png;base64,${d.image}" download="visual-comparison.png">DOWNLOAD COMPARISON </a>`;}catch(err){document.querySelector('#visual-diff').textContent=err.message;}}
function render(){const previous=document.activeElement,focusId=previous?.id,focusAction=previous?.dataset?.action,focusValue=previous?.dataset?.value;state.progressAnimation?.pause();state.scope?.revert();let html=state.route==='check'?(state.job?scanning():landing()):state.route==='report'?report():state.route==='history'?history():state.route==='reports'?reports():state.route==='help'?help():state.route==='settings'?settings():state.route==='schedules'?schedules():state.route==='compare'?compare():landing();main.innerHTML=html;if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});else if(focusAction)[...main.querySelectorAll('[data-action]')].find(el=>el.dataset.action===focusAction&&el.dataset.value===focusValue)?.focus({preventScroll:true});updateNav();motion();if(state.job&&state.route==='check')updateProgress(state.job);}
function renderError(message,detail='',retry=false){state.scope?.revert();main.innerHTML=`<section class="container"><div class="error-view"><span class="label">◇ CHECK INTERRUPTED</span><h1>${e(message)}</h1><p>Check the URL and connection, or try again. Some websites block automated requests.</p>${detail?`<details><summary>Technical details</summary><pre>${e(detail)}</pre></details>`:''}<div class="head-actions">${retry?button('TRY AGAIN ','retry','primary'):''}${button('BACK TO CHECK','clear-job')}</div></div></section>`;}
function renderReportTab(){const template=document.createElement('template');template.innerHTML=report();const body=main.querySelector('.report-body');utils.remove(body);body.style.transform='';body.style.opacity='1';body.replaceChildren(...template.content.querySelector('.report-body').childNodes);const tab=location.hash.split('/')[2]||'findings';main.querySelectorAll('.report-tabs button').forEach(b=>{const active=b.dataset.action==='tab-'+tab;b.classList.toggle('active',active);b.setAttribute('aria-current',active?'page':'false');});if(!media.matches)state.scope.add(()=>animate(body,{opacity:[.75,1],y:[4,0],duration:220,ease:'out(3)'}));}
async function route(){const token=++state.loadToken;const [view,id]=location.hash.replace(/^#/,'').split('/');state.route=view||'check';if(view==='report'&&state.scan?.id===id&&main.querySelector('.report-body')){renderReportTab();updateNav();return;}if(view==='report'){main.setAttribute('aria-busy','true');main.innerHTML='<section class="container"><div class="page-head"><h1>Opening analysis.</h1></div><div class="report-loading" role="status">Loading saved findings…<div class="loading-skeleton"></div><div class="loading-skeleton" style="width:45%"></div></div></section>';try{const result=await api('/api/scan/'+id);if(token!==state.loadToken)return;const changed=state.scan?.id!==result.scan.id;state.scan=result.scan;state.summary=result.summary;if(changed){state.selected=null;state.filter='All';state.category='';state.page='';state.search='';state.status='';state.listPage=1;state.pageIndex=0;}render();}catch(err){renderError('This analysis could not be opened.',err.message);}finally{main.removeAttribute('aria-busy');}}else render();document.querySelector('nav').classList.remove('open');document.querySelector('.mobile-nav').setAttribute('aria-expanded','false');}
function openDrawer(title,content){utils.remove(drawer);state.drawerReturn=document.activeElement;document.querySelector('#drawer-title').textContent=title;document.querySelector('#drawer-content').innerHTML=content;drawer.showModal();if(!media.matches)animate(drawer,{x:[36,0],opacity:[0,1],duration:300,ease:'out(3)'});}
function restoreFocus(){if(state.drawerReturn?.isConnected){state.drawerReturn.focus();return;}const action=state.drawerReturn?.dataset?.action,value=state.drawerReturn?.dataset?.value;const target=[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===action&&el.dataset.value===value);(target||main).focus();}
function closeDrawer(){utils.remove(drawer);if(media.matches){drawer.close();restoreFocus();}else animate(drawer,{x:24,opacity:0,duration:190,ease:'in(2)',onComplete:()=>{drawer.close();restoreFocus();}});}
function scanSettings(){const o=options;openDrawer('Configure the inspection.',`<form id="scan-options"><div class="form-grid"><div class="field"><label for="max-pages">Page limit</label><select id="max-pages" name="max_pages">${[1,5,10,20,30].map(v=>`<option ${o.max_pages===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="profile">Profile</label><select id="profile" name="profile">${['Business website','Portfolio','Online store','Blog','Custom'].map(v=>`<option ${o.profile===v?'selected':''}>${v}</option>`).join('')}</select></div></div><div class="form-grid"><div class="field"><label for="max-requests">Request limit</label><input id="max-requests" name="max_requests" type="number" min="20" max="500" value="${o.max_requests}"></div><div class="field"><label for="max-seconds">Time limit / seconds</label><input id="max-seconds" name="max_seconds" type="number" min="30" max="600" value="${o.max_seconds}"></div></div><div class="field"><label for="image-kb">Large image threshold / KB</label><input id="image-kb" name="image_kb" type="number" min="100" max="10000" value="${o.image_kb}"></div><div class="form-section"><h3>What to inspect.</h3><div class="checkbox-grid">${state.boot.options.categories.map(c=>`<label class="check-label"><input type="checkbox" name="categories" value="${c}" ${(o.categories||[]).includes(c)?'checked':''}>${c}</label>`).join('')}</div></div><div class="form-section"><h3>Browser & content.</h3><label class="check-label"><input name="browser" type="checkbox" ${o.browser?'checked':''}> Include browser previews</label><p class="small-note">Requires Chromium. Adds rendered layout, contrast, keyboard, print and reduced-motion observations.</p><div class="form-grid"><div class="field"><label for="browser-pages">Browser page limit</label><input id="browser-pages" name="browser_pages" type="number" min="1" max="5" value="${o.browser_pages}"></div><div class="field"><label for="language">Spelling language</label><select id="language" name="language">${['en','es','fr','de','pt','it'].map(v=>`<option ${o.language===v?'selected':''}>${v}</option>`).join('')}</select></div></div><label class="check-label"><input name="spelling" type="checkbox" ${o.spelling?'checked':''}> Check spelling</label><label class="check-label" style="margin-top:12px"><input name="form_checks" type="checkbox" ${o.form_checks?'checked':''}> Inspect native form validity</label><p class="small-note">Reads validity state only. Does not fill or submit forms.</p></div><div class="form-section"><h3>Rules & journeys.</h3>${[['dictionary','Allowed dictionary words'],['required_phrases','Required phrases on each page'],['forbidden_phrases','Outdated wording'],['journey','Journey URLs or paths in order']].map(([k,label])=>`<div class="field"><label for="option-${k}">${label} / one per line</label><textarea id="option-${k}" name="${k}">${e((o[k]||[]).join('\n'))}</textarea></div>`).join('')}<p class="small-note">Journey checks inspect URL reachability and links between steps. They do not complete transactions.</p></div><button type="submit" class="button primary form-submit">APPLY SETTINGS </button></form>`);}
async function reviewDrawer(id){const i=state.scan.issues.find(i=>i.id===id),r=state.boot.reviews[id]||{};openDrawer('Make the next step clear.',`<p class="small-note">${e(i.title)}</p><form id="review-form" data-id="${id}"><div class="field"><label for="review-status">Work status</label><select id="review-status" name="status">${['Open','In progress','Fixed (manual)','Intentional','Needs review'].map(v=>`<option ${(r.status||'Open')===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-grid"><div class="field"><label for="review-owner">Owner</label><input id="review-owner" name="owner" value="${e(r.owner||'')}"></div><div class="field"><label for="review-due">Due date</label><input id="review-due" name="due" type="date" value="${e(r.due||'')}"></div></div><label class="check-label"><input type="checkbox" name="blocker" ${r.blocker?'checked':''}> Mark as a launch blocker</label><div class="field" style="margin-top:20px"><label for="review-notes">Review note / reason for an exception</label><textarea id="review-notes" name="notes">${e(r.notes||'')}</textarea></div><div class="field"><label for="review-image">Attach evidence / PNG or JPG</label><input id="review-image" name="image" type="file" accept="image/png,image/jpeg"><small>Use an image under 8 MB.</small></div><div id="review-error" role="alert"></div><button type="submit" class="button primary form-submit">SAVE REVIEW </button></form>`);}
const manualChecks=['Keyboard focus is visible and follows a sensible order','Menus and dialogs work with keyboard and Escape','No keyboard trap blocks navigation','Forms explain required fields and errors','Controlled form test shows the expected success state','Mobile content is readable and important controls are reachable','Popups are dismissible and do not hide essential content','Print view preserves important information','Reduced-motion behavior is appropriate','Policy links, business details and claims have been reviewed'];
async function manualDrawer(){const page=pageObj().url,saved=await api('/api/manual?page='+encodeURIComponent(page));openDrawer('Complete the picture.',`<p class="small-note">${e(page)}<br>Record your own inspection. Test form submissions only in an authorized test environment.</p><form id="manual-form" data-page="${e(page)}">${manualChecks.map((c,i)=>`<div class="field"><label for="manual-${i}">${c}</label><select id="manual-${i}" name="check-${i}">${['Not reviewed','Pass','Needs work','Not applicable'].map(v=>`<option ${saved[c]===v?'selected':''}>${v}</option>`).join('')}</select></div>`).join('')}<div class="field"><label for="manual-notes">Review notes</label><textarea id="manual-notes" name="notes">${e(saved.notes||'')}</textarea></div><button type="submit" class="button primary form-submit">SAVE CHECKLIST </button></form>`);}
async function fileData(file){if(!file||!file.size)return undefined;if(file.size>8_000_000)throw new Error('Use an image under 8 MB.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file);});}
async function download(kind,issue=''){const btn=document.querySelector(`[data-action="export-${kind}"]`);const label=btn?.innerHTML;if(btn){btn.disabled=true;btn.textContent='PREPARING…';}try{const url='/api/export?id='+state.scan.id+'&kind='+kind+'&brand='+encodeURIComponent(document.querySelector('#report-brand')?.value||state.boot.settings.report_brand)+(issue?'&issue='+issue:'');const res=await fetch(url);if(!res.ok){let err=await res.json();throw new Error(err.error);}const blob=await res.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=kind==='card'?'issue-'+issue+'.md':kind==='zip'?'website-review-archive.zip':'website-review.'+kind;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Your download is ready.');}finally{if(btn){btn.disabled=false;btn.innerHTML=label;}}}
function rerenderFindings(){const focused=document.activeElement,id=focused?.id,pos=focused?.selectionStart;const items=filteredIssues();state.listPage=Math.min(state.listPage,Math.max(1,Math.ceil(items.length/20)));if(!items.some(i=>i.id===state.selected))state.selected=items[0]?.id;const content=document.querySelector('#findings-content');content.innerHTML=findingContent(items,items.slice((state.listPage-1)*20,state.listPage*20));if(!media.matches)animate(content,{opacity:[.5,1],duration:160,ease:'out(2)'});if(id){const next=document.getElementById(id);next?.focus();if(pos!==undefined&&next?.setSelectionRange)next.setSelectionRange(pos,pos);}}
let searchTimer;
document.addEventListener('input',ev=>{if(ev.target.id==='issue-search'){state.search=ev.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(rerenderFindings,100);}});
document.addEventListener('change',async ev=>{try{if(ev.target.id==='issue-page'){state.page=ev.target.value;state.listPage=1;rerenderFindings();}if(ev.target.id==='issue-status'){state.status=ev.target.value;state.listPage=1;rerenderFindings();}if(ev.target.id==='page-select'){state.pageIndex=Number(ev.target.value);render();}if(ev.target.id==='visual-pair')await showVisual(Number(ev.target.value));}catch(err){toast(err.message);}});
document.addEventListener('click',async ev=>{const trigger=ev.target.closest('[data-action]');if(!trigger)return;const action=trigger.dataset.action,value=trigger.dataset.value;try{if(['check','history','reports','help','settings','schedules','compare'].includes(action)){location.hash='#'+action;return;}if(action.startsWith('tab-')){location.hash='#report/'+state.scan.id+'/'+action.slice(4);return;}if(action==='open-scan'||action==='open-report'){location.hash='#report/'+value+'/'+(action==='open-report'?'report':'findings');return;}if(action==='scan-settings')scanSettings();if(action==='filter'){state.filter=value;state.listPage=1;render();}if(action==='category'){state.category=state.category===value?'':value;state.listPage=1;render();}if(action==='reset-filters'){Object.assign(state,{filter:'All',category:'',page:'',search:'',status:'',listPage:1});render();}if(action==='select-issue'){state.selected=value;document.querySelectorAll('.finding-row').forEach(r=>{let active=r.dataset.value===value;r.classList.toggle('selected',active);r.setAttribute('aria-pressed',String(active));});const panel=document.querySelector('#finding-detail');utils.remove(panel);panel.innerHTML=detail(state.scan.issues.find(i=>i.id===value));document.querySelector('.finding-layout').classList.add('mobile-focused');if(!media.matches)animate(panel,{opacity:[.4,1],x:[8,0],duration:210,ease:'out(3)'});if(matchMedia('(max-width:760px)').matches){panel.scrollIntoView({behavior:media.matches?'instant':'smooth',block:'start'});panel.querySelector('button')?.focus({preventScroll:true});}}if(action==='detail-back'){document.querySelector('.finding-layout').classList.remove('mobile-focused');document.querySelector('.finding-row.selected')?.focus();}if(action==='previous-issues'||action==='next-issues'){state.listPage+=action==='next-issues'?1:-1;rerenderFindings();}if(action==='review')await reviewDrawer(value);if(action==='manual')await manualDrawer();if(action==='copy'){await navigator.clipboard.writeText(value);toast('Location copied.');}if(action==='download-card')await download('card',value);if(action.startsWith('export-'))await download(action.slice(7));if(action==='preview'){state.preview=value;render();}if(action==='page-node'){state.pageIndex=Number(value);render();}if(action==='recheck'){await beginScan(value,true,{...state.scan.options,max_pages:1,journey:[]});toast('Rechecking one page. A new scan will be saved.');}if(action==='cancel'){await api('/api/cancel',{id:state.job.id});trigger.disabled=true;trigger.textContent='CANCELLING…';}if(action==='retry'){let old=state.job;state.job=null;await beginScan(old.url,true,old.options);}if(action==='clear-job'){state.job=null;clearTimeout(pollTimer);location.hash='#check';render();}if(action==='toggle-schedule'){await api('/api/schedule/toggle',{id:Number(value),enabled:trigger.dataset.enabled==='true'});await refresh();render();toast('Schedule updated.');}if(action==='mark-read'){await api('/api/notifications/read',{});await refresh();render();toast('Notifications marked read.');}}catch(err){toast(err.message);}});
document.addEventListener('submit',async ev=>{const form=ev.target;ev.preventDefault();const data=new FormData(form),submit=form.querySelector('[type="submit"]');const original=submit?.innerHTML;if(submit){submit.disabled=true;submit.textContent='WORKING…';}try{if(form.id==='url-form'){await beginScan(data.get('url'),data.get('consent')==='on');}if(form.id==='scan-options'){let raw={...options};for(const k of ['max_pages','max_requests','max_seconds','image_kb','browser_pages'])raw[k]=Number(data.get(k));for(const k of ['browser','spelling','form_checks'])raw[k]=data.get(k)==='on';for(const k of ['profile','language'])raw[k]=data.get(k);for(const k of ['dictionary','required_phrases','forbidden_phrases','journey'])raw[k]=splits(String(data.get(k)||''));raw.categories=data.getAll('categories');if(raw.profile==='Portfolio')raw.image_kb=Math.min(raw.image_kb,350);if(['Blog','Online store'].includes(raw.profile))raw.spelling=true;options=raw;closeDrawer();toast('Scan settings applied.');}if(form.id==='review-form'){const review={status:data.get('status'),owner:data.get('owner'),due:data.get('due'),notes:data.get('notes'),blocker:data.get('blocker')==='on'};await api('/api/review',{id:form.dataset.id,review,image:await fileData(data.get('image'))});await refresh();closeDrawer();render();toast('Review saved.');}if(form.id==='manual-form'){let review={notes:data.get('notes')};manualChecks.forEach((c,i)=>review[c]=data.get('check-'+i));await api('/api/manual',{page:form.dataset.page,review});closeDrawer();toast('Manual checklist saved.');}if(form.id==='settings-form'){await api('/api/settings',{report_brand:data.get('report_brand'),brand_rules:{dictionary:splits(data.get('dictionary')),required_phrases:splits(data.get('required_phrases')),forbidden_phrases:splits(data.get('forbidden_phrases'))},image:await fileData(data.get('logo'))});await refresh();options={...options,...state.boot.settings.brand_rules};toast('Workspace settings saved.');}if(form.id==='schedule-form'){await api('/api/schedule',{scan_id:data.get('scan_id'),hours:Number(data.get('hours'))});await refresh();render();toast('Recurring scan saved. Keep the worker running.');}if(form.id==='compare-form')await showComparison(data.get('before'),data.get('after'));if(form.id==='login-form'){await api('/api/login',{password:data.get('password')});await initialize();}}catch(err){let area=form.id==='url-form'?document.querySelector('#url-error'):form.id==='review-form'?document.querySelector('#review-error'):null;if(area){area.innerHTML=`<div class="inline-error"><span>◇</span><p>${e(err.message)}</p></div>`;area.scrollIntoView({block:'nearest'});}else toast(err.message);}finally{if(submit?.isConnected){submit.disabled=false;submit.innerHTML=original;}}});
drawer.addEventListener('click',ev=>{if(ev.target===drawer||ev.target.closest('[data-close]'))closeDrawer();});drawer.addEventListener('cancel',ev=>{ev.preventDefault();closeDrawer();});
document.querySelector('.mobile-nav').onclick=()=>{const nav=document.querySelector('.header nav'),open=nav.classList.toggle('open');document.querySelector('.mobile-nav').setAttribute('aria-expanded',String(open));if(open&&!media.matches)animate(nav,{opacity:[0,1],y:[-5,0],duration:180,ease:'out(3)'});};
document.addEventListener('pointerdown',ev=>{const el=ev.target.closest('button,.button');if(!el||el.disabled||media.matches)return;utils.remove(el);animate(el,{scale:.98,duration:90,ease:'out(2)'});});
function release(ev){const el=ev.target.closest('button,.button');if(!el||media.matches)return;utils.remove(el);animate(el,{scale:1,duration:140,ease:'out(3)'});}
document.addEventListener('pointerup',release);document.addEventListener('pointercancel',release);
window.addEventListener('hashchange',route);media.addEventListener('change',()=>{state.scope?.revert();if(media.matches)utils.remove('.scan-signal');else motion();});
async function initialize(){try{const auth=await api('/api/auth');if(auth.required&&!auth.authorized){main.innerHTML=`<div class="login"><span class="label">PRIVATE WORKSPACE</span><h1 style="margin-top:20px">A closer look starts here.</h1><p>Enter your workspace password to open saved reviews and start a scan.</p><form id="login-form"><div class="field"><label for="password">Workspace password</label><input id="password" name="password" type="password" autocomplete="current-password" required></div><button type="submit" class="button primary">OPEN WORKSPACE </button></form></div>`;return;}await refresh();const pending=sessionStorage.getItem('wqc_job');if(pending){try{const job=await api('/api/job/'+pending);if(['running','queued'].includes(job.state)){state.job=job;poll(pending);}else sessionStorage.removeItem('wqc_job');}catch{sessionStorage.removeItem('wqc_job');}}await route();}catch(err){renderError('Your workspace could not be opened.',err.message);}}
initialize();
